    doneDate: { time: false },
    startTime: { time: true },
    endTime: { time: true },
    client: { relation: { targetProjectId: ids.cabinetId } },
    service: { relation: { targetProjectId: ids.cabinetId } },
    // A client's card, from its visits in this project…
    [R3.sessions]: back(ids.cabinetId, "client", "sessions", "sum"),
    [R3.paid]: back(ids.cabinetId, "client", "paidAmount", "sum"),
    [R3.debt]: back(ids.cabinetId, "client", "debt", "sum"),
