    [R3.training]: back(ids.trackerId, "person", "trainingMinutes", "sum"),
    [R3.sleep]: back(ids.trackerId, "person", "sleep", "avg"),
    // A service, from the visits that name it.
    [R3.revenue]: back(ids.cabinetId, "service", "paidAmount", "sum"),
